use std::fmt;

/// A point in 2D space.
#[derive(Debug, Clone, PartialEq)]
struct Point {
    x: f64,
    y: f64,
}

impl Point {
    fn new(x: f64, y: f64) -> Self {
        Self { x, y }
    }

    fn distance(&self, other: &Point) -> f64 {
        let dx = self.x - other.x;
        let dy = self.y - other.y;
        (dx * dx + dy * dy).sqrt()
    }
}

impl fmt::Display for Point {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "({}, {})", self.x, self.y)
    }
}

fn main() {
    let origin = Point::new(0.0, 0.0);
    let p = Point::new(3.0, 4.0);
    println!("Distance from {} to {}: {}", origin, p, origin.distance(&p));
}

// Retry calls fn up to n times with exponential backoff.
func Retry(n int, fn func() error) error {
	var err error
	for i := range n {
		if err = fn(); err == nil {
			return nil
		}
		delay := time.Duration(1<<i) * 100 * time.Millisecond
		slog.Warn("retrying", "attempt", i+1, "err", err)
		time.Sleep(delay)
	}
	return fmt.Errorf("failed after %d attempts: %w", n, err)
}

