// Return a greeting for each name in the list
std::string greetAll(const std::vector<std::string>& names) {
    std::string result;
    result.reserve(names.size() * 32);
    for (const auto& name : names) {
        result += std::format("Hello, {}!\n", name);
    }
    return result;
}

int main() {
    auto msg = greetAll({"Alice", "Bob", "Carol"});
    return msg.empty() ? 1 : 0;
}

