/** Formats a product summary for display. */
public class ProductFormatter {

    private static final int MAX_TAGS = 5;

    public String format(String name, double price, List<String> tags) {
        var tagLine = String.join(", ", tags.stream()
                .limit(MAX_TAGS)
                .toList());
        return "%-20s $%.2f  [%s]".formatted(name, price, tagLine);
    }
}

// Fetch user profile with a fallback display name
data class User(val id: Int, val name: String, val email: String)

fun formatGreeting(user: User?): String {
    if (user == null) return "Hello, Guest!"
    val display = user.name.ifBlank { "User #${user.id}" }
    return "Hello, $display! (${user.email})"
}

fun main() {
    val users = listOf(
        User(1, "Ada Lovelace", "ada@example.com"),
        User(2, "", "anon@example.com")
    )
    users.forEach { println(formatGreeting(it)) }
}

