// Formats a greeting with a countdown to an event
public static string FormatEventGreeting(
    string name,
    DateTime eventDate)
{
    int daysLeft = (eventDate - DateTime.Today).Days;

    if (daysLeft < 0)
        return $"Hey {name}, the event has passed!";

    return daysLeft == 0
        ? $"Hey {name}, the event is today!"
        : $"Hey {name}, only {daysLeft} days left!";
}

import Foundation

// Format a duration into a human-readable string
func formatDuration(_ seconds: Double) -> String {
    let minutes = Int(seconds) / 60
    let secs = Int(seconds) % 60
    guard seconds >= 0 else { return "invalid" }
    return "\(minutes)m \(secs)s"
}

