# Fetch paginated results from a remote API
class ApiClient
  BASE_URL = "https://api.example.com/v1"

  def initialize(token)
    @token = token
    @retries = 3
  end

  def fetch_users(page: 1, per_page: 50)
    url = "#{BASE_URL}/users?page=#{page}&per_page=#{per_page}"
    response = get(url)
    response[:data].map { |u| u[:name] }
  end
end

# Returns disk usage summary for a given path
function Get-DiskSummary {
    param(
        [string]$Path = $env:USERPROFILE,
        [int]$TopN = 5
    )
    $items = Get-ChildItem -Path $Path -ErrorAction SilentlyContinue
    $results = $items | ForEach-Object {
        $size = (Get-ChildItem $_.FullName -Recurse -File `
            -ErrorAction SilentlyContinue |
            Measure-Object -Property Length -Sum).Sum ?? 0
        [PSCustomObject]@{ Name = $_.Name; SizeMB = [math]::Round($size / 1MB, 2) }
    }
    $results | Sort-Object SizeMB -Descending | Select-Object -First $TopN |
        Format-Table -AutoSize
}

/**
 * Formats a duration in milliseconds into a human-readable string.
 * @param {number} ms - Duration in milliseconds
 * @returns {string}
 */
function formatDuration(ms) {
  const units = [
    { label: "h", value: 3_600_000 },
    { label: "m", value: 60_000 },
    { label: "s", value: 1_000 },
  ];

  const parts = units.reduce((acc, { label, value }) => {
    const count = Math.floor(ms / value);
    ms %= value;
    return count > 0 ? [...acc, `${count}${label}`] : acc;
  }, []);

  return parts.length > 0 ? parts.join(" ") : "0s";
}

// Fetch a paginated resource with typed results
interface Page<T> {
  items: T[];
  total: number;
  cursor?: string;
}

async function fetchPage<T>(
  endpoint: string,
  limit = 20,
  cursor?: string,
): Promise<Page<T>> {
  const params = new URLSearchParams({ limit: String(limit) });
  if (cursor) params.set("cursor", cursor);
  const url = `${endpoint}?${params}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${url}`);
  return res.json() as Promise<Page<T>>;
}

